                SmlGrid.getContextMenuParams = getContextMenuParams;
                // TODO: dočasné - až bude zaktualizována varianta Eko, tak ji použít nebo tohle přesunout do Eko.WebClient
                SmlGrid.presetDokumentColumns = ["pozice_spis_ico", "ixp_spis", "priz_spis" /*, "ixs_fun_akt"*/, "ixs_su_akt", "nazev", "akt_znacka", "stav_dist", "stav_pis" /*, "typ_ag"*/ /*, "ktg_typ"*/ /*, "ixs_typ"*/, "s_prij", "s_ssl", "dat_zmena", "zmenu_prov", "s_ele", "s_fyz", "uzo", "spis_pl", "spis_znak", "ixs_fun_wfl", "ixs_su_wfl", "dat_vyriz", "s_schval", "skar_znak", "skar_lhuta", "rok_spo_uda", "rok_skartace", "poc_listu", "poc_stran", "poc_kop", "poc_priloh", "poc_l_priloh", "cj", "PrizVBaliku", "ixs_zup", "PrizPozSkar", "typ_entity_ico", "technicke_vlastnosti_ico"];
                // TODO: těmto hodnotám musí odpovídat filtry (s prefixem dokument_)
