                let Comparator;
                (function (Comparator) {
                    /**
                     * vytvoření porovnávače ve standardním seznamu
                     *
                     * @param {GContent & IGStandardSmlGrid<TDto, TPermissions>} gcontent content
                     */
                    function create(gcontent) {
                        let that = gcontent;
                        // porovnání
                        that.comparisonBadge = new GObservableObject({ value: "0" });
                        that.comparisonCnt = $("<div class='no-border'>").append($("<h3>", { text: "jres:24100004", style: "margin: 0.5rem" })); //RC 24100004 : Vyberte alespoň dvě položky v seznamu
                        that.element.gsidebar("addPanel", "right", {
                            leaf: { caption: "jres:24100003", badge: that.comparisonBadge }, //RC 24100003 : Porovnání
                            id: "rightComparisonPanel",
                            pinned: false,
                            icon: "fa-balance-scale",
                            customDiv: that.comparisonCnt
                        });
                    }
                    Comparator.create = create;
                    /**
                     * Přidání vybraných řádků do porovnávače
                     *
                     * @param {GContent & IGStandardSmlGrid<TDto, TPermissions>} gcontent content
                     */
                    function add(gcontent) {
                        let that = gcontent;
                        // vybrané řádky
                        let rows = that.element.find(".SeznamSml.ggrid").ggrid("getSelection", true);
                        if (rows.length > 0) {
                            let dataRows = rows.map(function (item, idx) { return item.data; });
                            if (that.isComparisonInited) {
                                // přidání do existujícího porovnávače
                                that.comparator.gcomparator("addItems", dataRows);
                            }
                            else {
                                // vytvoření nového porovnávače
                                that.comparisonCnt.empty();
                                that.comparator = $('<div class="js-comparator">').appendTo(that.comparisonCnt).gcomparator({
                                    items: dataRows,
                                    columns: that.element.find(".SeznamSml.ggrid").ggrid("trueColumns").filter(c => c.caption),
                                    itemTemplate: that.PrimaryKey.split(",").map(pk => "{" + pk + "}").join(", "),
                                    itemchange: function (ev, ctx) {
                                        that.comparisonBadge.value = ctx.count.toString();
                                        that.comparisonBadge.update();
                                    },
                                    selection: function (ev, ctx) {
                                        that.element.find(".SeznamSml.ggrid").ggrid("activeRow", ctx.item);
                                    }
                                });
                                that.isComparisonInited = true;
                            }
                            // shození zatržítek
                            for (let row in rows) {
                                rows[row].checked = false;
                            }
                            that.element.find(".SeznamSml.ggrid").ggrid("refresh");
                        }
                    }
                    Comparator.add = add;
                })(Comparator = SmlGrid.Comparator || (SmlGrid.Comparator = {}));
