                    /**
                     * Vrátí parametry pro zobrazení seznamu rezervací
                     *
                     * @param {string} agenda agenda (BPL, HPL, UCT, FUC, BUC)
                     * @returns {any} parametry
                     */
                    function getParamsForTabRezervace(agenda) {
                        let result = {};
                        // gridformat
                        result["gridFormat"] = createGridFormatRezervace(agenda);
                        // sloupce
                        switch (agenda) {
                            case "BPL":
                                result["columnList"] = "zkr_ag,s,rok_sml,cislo_sml,ktg_typ_zkr,ixp,ac,ac_ag,ac_esu,ico_esu,nazev_esu,popis,dat_evid,c_celkem,c_rez,dat_spl,dat_uhr,dat_zau,vs,ks,ss,bu_vl_txt,bu_ci_txt,zp_zkr,ixp_den_txt,ixs_fun_akt_txt,dat_zmena";
                                break;
                            case "HPL":
                                result["columnList"] = "zkr_ag,s,stav,rok_sml,cislo_sml,ixp,ac,ac_ag,ico_esu,nazev_esu,popis,dat_evid,c_celkem,c_rez,kod_kon,vs,ss,zp_zkr,ixp_den_txt,ixs_fun_akt_txt,dat_zmena";
                                break;
                            case "UCT":
                                result["columnList"] = "zkr_ag,s,rok_sml,cislo_sml,ixp,ac,ac_ag,popis,dat_evid,c_celkem,c_rez,radek,ixp_den_txt,ixs_fun_akt_txt,dat_zmena";
                                break;
                            case "FUC":
                                result["columnList"] = "zkr_ag,s,rok_sml,cislo_sml,ixp,ac,ac_ag,ico_esu,nazev_esu,popis,dat_evid,c_celkem,c_rez,radek,vs,ss,ixp_den_txt,ixs_fun_akt_txt,dat_zmena";
                                break;
                            case "BUC":
                                result["columnList"] = "zkr_ag,s,rok_sml,cislo_sml,ixp,ac,ac_ag,ico_esu,nazev_esu,popis,dat_evid,c_celkem,c_rez,radek,vs,ss,ixp_den_txt,zp_zkr,ixs_fun_akt_txt,dat_zmena";
                                break;
                        }
                        // podmíněné formátování
                        result["condFormats"] = [
                            {
                                formula: "@c_rez == 0",
                                text: Gordic.Components.Grid.CondFormats.CondFormatText.red
                            }
                        ];
                        return result;
                    }
