                /**
                 * Spojení dat a výsledku hromadné operace (přes zadané sloupce) do výsledku hromadné operace
                 *
                 * @param {T[]} data data
                 * @param {Gordic.Isl.GServiceGroupResponse<T>} response výsledek hromadné operace (z dat jsou vyplněny jen primární klíče)
                 * @param {string} keys primární klíč
                 * @returns {Gordic.Isl.GServiceGroupResponse<T>} výsledek hromadné operace s daty
                 */
                function joinDataAndResponseToIslGroupResponse(data, response, keys) {
                    return {
                        result: response.result.map(res => {
                            res.data = $.extend(res.data, data.find(i => {
                                let areTheSame = true;
                                keys.split(",").forEach(key => {
                                    if (i[key] !== res.data[key])
                                        areTheSame = false;
                                });
                                return areTheSame;
                            }));
                            // TODO: je možné tohle dělat vždy nebo jen pro případ průvodce bez wfltpre?
                            if (res.data["wiz_txt_err"] || res.data?.wiz_txt_err === "")
                                delete res.data["wiz_txt_err"];
                            if (res.data["wiz_kind"])
                                delete res.data["wiz_kind"];
                            if (res.data["wiz_check"])
                                delete res.data["wiz_check"];
                            return res;
                        })
                    };
                }
                SmlWizard.joinDataAndResponseToIslGroupResponse = joinDataAndResponseToIslGroupResponse;
                ///**
